import heapq

def k_smallest_pairs(nums1, nums2, k):
    if not nums1 or not nums2:
        return []
    heap = []
    for i in range(min(k, len(nums1))):
        for j in range(min(k, len(nums2))):
            if -heapq.nsmallest(1, heap)[0][0] > nums1[i] + nums2[j]:
                heapq.heappush(heap, (-(nums1[i] + nums2[j]), [nums1[i], nums2[j]]))
            if len(heap) > k:
                heapq.heappop(heap)
    return [heapq.heappop(heap)[1] for _ in range(k)][::-1] if k > len(nums1) * len(nums2) else [heapq.heappop(heap)[1] for _ in range(len(heap))][::-1]
